insert into public.jobs (job_key, title, jd_version, description, location_label, work_mode) values ('LCA_CONSULTANT', 'Life Cycle Assessment (LCA) Consultant', 'lca-jd-2026-11-v1', 'Build Life Cycle Inventory (LCI) datasets, run LCA studies and benchmark results against industry peers for a sustainability consultancy client in Chennai (onsite). Requires 2–3 years running LCA projects independently (the problem summary says 4–6; both kept as scenarios), hands-on GaBi or SimaPro, at least three completed LCA projects, ISO 14040/14044. Environmental degree highly desired; EPD experience preferred; relocation, travel and a one-year commitment are confirmed with the candidate.', 'Chennai (client site)', 'Onsite, full-time') on conflict (job_key, jd_version) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'lca-rubric-1.0.0', 'lca_experience', 'Relevant LCA professional experience', 'Relevant LCA professional experience', 10, false, '{"direct":"Dated professional roles explicitly doing LCA work, meeting the active experience scenario from non-overlapping intervals.","related":"Some LCA or sustainability experience, or academic LCA research, below the active scenario or not professional.","notEvidence":"No relevant experience, or dates/domain cannot be validated."}'::jsonb, 1 from public.jobs where job_key = 'LCA_CONSULTANT' and jd_version = 'lca-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'lca-rubric-1.0.0', 'lca_project_delivery', 'Independent LCA study delivery and completed projects', 'Independent LCA study delivery and completed projects', 20, false, '{"direct":"Distinct LCA studies described as completed, with scope, role or deliverable.","related":"LCA activity in responsibilities or academic work; completion, independence or count unclear.","notEvidence":"No LCA project evidence."}'::jsonb, 2 from public.jobs where job_key = 'LCA_CONSULTANT' and jd_version = 'lca-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'lca-rubric-1.0.0', 'lca_software', 'GaBi / SimaPro software proficiency', 'GaBi / SimaPro software proficiency', 15, false, '{"direct":"Hands-on GaBi or SimaPro use in a project or study, with context.","related":"OpenLCA or another LCA tool, or GaBi/SimaPro only listed without context.","notEvidence":"No LCA tool evidence."}'::jsonb, 3 from public.jobs where job_key = 'LCA_CONSULTANT' and jd_version = 'lca-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'lca-rubric-1.0.0', 'lci_data', 'LCI data collection, validation and quality control', 'LCI data collection, validation and quality control', 15, false, '{"direct":"Collecting, compiling, validating or standardising life-cycle inventory data with quality context.","related":"Environmental, activity or emissions data work without clear LCI context.","notEvidence":"No inventory data evidence."}'::jsonb, 4 from public.jobs where job_key = 'LCA_CONSULTANT' and jd_version = 'lca-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'lca-rubric-1.0.0', 'iso_modelling', 'ISO 14040/14044, boundaries, allocation and modelling', 'ISO 14040/14044, boundaries, allocation and modelling', 15, false, '{"direct":"Applied ISO 14040/44, system boundaries, allocation or documented modelling assumptions.","related":"Standards listed, or partial methodology without clear application.","notEvidence":"No methodology evidence."}'::jsonb, 5 from public.jobs where job_key = 'LCA_CONSULTANT' and jd_version = 'lca-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'lca-rubric-1.0.0', 'operational_data', 'Operational, manufacturing, energy and logistics data', 'Operational, manufacturing, energy and logistics data', 10, false, '{"direct":"Plant, process, energy, supplier or logistics data gathered for an assessment.","related":"General operations or supply-chain data work without LCA context.","notEvidence":"No operational data evidence."}'::jsonb, 6 from public.jobs where job_key = 'LCA_CONSULTANT' and jd_version = 'lca-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'lca-rubric-1.0.0', 'education', 'Environmental education / domain background', 'Environmental education / domain background', 5, false, '{"direct":"Environmental, sustainability or environmental engineering/science degree.","related":"Related engineering or science degree with transferable context.","notEvidence":"No relevant education evidence."}'::jsonb, 7 from public.jobs where job_key = 'LCA_CONSULTANT' and jd_version = 'lca-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'lca-rubric-1.0.0', 'benchmarking_epd', 'Benchmarking, research datasets and EPD', 'Benchmarking, research datasets and EPD', 5, false, '{"direct":"Public LCA databases, industry benchmarking or EPD work.","related":"Literature review or secondary data use without explicit LCA benchmarking/EPD.","notEvidence":"No relevant evidence."}'::jsonb, 8 from public.jobs where job_key = 'LCA_CONSULTANT' and jd_version = 'lca-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'lca-rubric-1.0.0', 'stakeholder', 'Stakeholder management and communication', 'Stakeholder management and communication', 5, false, '{"direct":"Client, supplier or cross-functional engagement with clear ownership.","related":"General teamwork or communication.","notEvidence":"No relevant evidence."}'::jsonb, 9 from public.jobs where job_key = 'LCA_CONSULTANT' and jd_version = 'lca-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.jobs (job_key, title, jd_version, description, location_label, work_mode) values ('UIUX_INTERN', 'UI/UX Design Intern (Growth For Impact)', 'uiux-jd-2026-11-v1', 'First design hire at Growth For Impact, a LinkedIn-like platform for sustainability. Design the website and job board, run user research, create high-fidelity Figma prototypes and specifications, keep a consistent design language and join design critiques. 0–1 year experience welcome; remote; stipend ₹10,000–15,000/month.', 'Remote', 'Remote internship, ₹10–15k/month') on conflict (job_key, jd_version) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'uiux-rubric-1.0.0', 'figma_prototyping', 'Figma and prototyping proficiency', 'Figma and prototyping proficiency', 20, false, '{"direct":"A project explicitly shows Figma use and a prototype or deliverable.","related":"Figma listed without project context, or another prototyping tool with context.","notEvidence":"No tool or prototype evidence."}'::jsonb, 1 from public.jobs where job_key = 'UIUX_INTERN' and jd_version = 'uiux-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'uiux-rubric-1.0.0', 'uxui_principles', 'UX/UI principles and human-centred design', 'UX/UI principles and human-centred design', 15, false, '{"direct":"Applied UX/UI or human-centred methods in an identifiable design project.","related":"Design thinking or general design vocabulary without a user-centred process.","notEvidence":"No relevant evidence."}'::jsonb, 2 from public.jobs where job_key = 'UIUX_INTERN' and jd_version = 'uiux-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'uiux-rubric-1.0.0', 'user_research', 'User research and understanding of psychology', 'User research and understanding of psychology', 15, false, '{"direct":"Interviews, usability testing, behavioural insight or validated user-needs work.","related":"General customer/user research without UX methods.","notEvidence":"No relevant evidence."}'::jsonb, 3 from public.jobs where job_key = 'UIUX_INTERN' and jd_version = 'uiux-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'uiux-rubric-1.0.0', 'interface_experience', 'Web and product interface design experience', 'Web and product interface design experience', 15, false, '{"direct":"Interface design decisions for a website, app or product (not only implementation).","related":"Web development or product work with little interface-design evidence.","notEvidence":"No relevant evidence."}'::jsonb, 4 from public.jobs where job_key = 'UIUX_INTERN' and jd_version = 'uiux-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'uiux-rubric-1.0.0', 'high_fidelity', 'High-fidelity prototypes and design specifications', 'High-fidelity prototypes and design specifications', 10, false, '{"direct":"High-fidelity prototype, interaction flow or design spec tied to a project.","related":"Wireframes, basic prototypes or vague design deliverables.","notEvidence":"No relevant evidence."}'::jsonb, 5 from public.jobs where job_key = 'UIUX_INTERN' and jd_version = 'uiux-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'uiux-rubric-1.0.0', 'visual_design', 'Visual design and aesthetic quality evidence', 'Visual design and aesthetic quality evidence', 10, false, '{"direct":"Only after a reviewer inspects a portfolio. V1 does not inspect portfolios, so this caps at Related.","related":"Resume describes visual design work but the artefact was not inspected.","notEvidence":"No visual work described."}'::jsonb, 6 from public.jobs where job_key = 'UIUX_INTERN' and jd_version = 'uiux-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'uiux-rubric-1.0.0', 'responsive_design', 'Responsive, multi-device design', 'Responsive, multi-device design', 5, false, '{"direct":"Design decisions that explicitly address multiple devices or breakpoints.","related":"Responsive implementation mentioned; design adaptation unclear.","notEvidence":"No relevant evidence."}'::jsonb, 7 from public.jobs where job_key = 'UIUX_INTERN' and jd_version = 'uiux-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'uiux-rubric-1.0.0', 'design_systems', 'Design systems and visual consistency', 'Design systems and visual consistency', 5, false, '{"direct":"Components, tokens, patterns or a maintained design system.","related":"Brand consistency or reusable UI elements without system-level detail.","notEvidence":"No relevant evidence."}'::jsonb, 8 from public.jobs where job_key = 'UIUX_INTERN' and jd_version = 'uiux-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
insert into public.job_criteria (job_id, rubric_version, criterion_key, label, description, weight, mandatory_verification, evidence_guidance, display_order) select id, 'uiux-rubric-1.0.0', 'collaboration', 'Collaboration and design critique', 'Collaboration and design critique', 5, false, '{"direct":"Design critiques, feedback iteration or cross-functional design delivery.","related":"General collaboration without design-specific review.","notEvidence":"No relevant evidence."}'::jsonb, 9 from public.jobs where job_key = 'UIUX_INTERN' and jd_version = 'uiux-jd-2026-11-v1' on conflict (job_id, rubric_version, criterion_key) do nothing;
